def project(family, name, requirement, seed, done, partial, untouched, checks, rationale):
    return {'family': 'engineering-' + family + '-v1', 'group': name,
            'requirement': requirement, 'seed_files': seed,
            'snapshots': {'DONE': done, 'PARTIAL': partial, 'NOT_STARTED': untouched},
            'checks': [{'name': n, 'argv': [sys.executable, '-c', source], 'files': {}} for n, source in checks],
            'rationale': rationale}


