        {'riff.rs': 'pub fn find(data:&[u8],id:&[u8;4])->Option<Vec<u8>> {\n    if data.len()<12 || &data[..4]!=b"RIFF" || &data[8..12]!=b"WAVE" {return None}\n    let size=u32::from_le_bytes(data[4..8].try_into().ok()?) as usize; if size.checked_add(8)?!=data.len() {return None}\n    let mut pos=12; let mut found=None;\n    while pos<data.len() {\n        let header=data.get(pos..pos+8)?; let n=u32::from_le_bytes(header[4..8].try_into().ok()?) as usize;\n        let end=(pos+8).checked_add(n)?; let payload=data.get(pos+8..end)?; let next=end.checked_add(n%2)?; if next>data.len() {return None}\n        if &header[..4]==id && found.is_none() {found=Some(payload.to_vec())}; pos=next;\n    }; found\n}\n', 'report.rs': 'use crate::riff::find;\npub fn chunk_len(data:&[u8],id:&[u8;4])->Option<usize> { find(data,id).map(|v|v.len()) }\n'},
